-- ==============================================================================\n-- Migration: 004_protect_trip_membership_metadata.sql\n-- Description: Prevent non-owners from changing trip ownership or membership\n--              metadata through otherwise permitted trip updates.\n-- ==============================================================================\n\nCREATE OR REPLACE FUNCTION public.protect_trip_membership_metadata()\nRETURNS TRIGGER\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nBEGIN\n  -- Ownership is immutable. Transfer ownership should be implemented as a\n  -- dedicated, audited operation rather than an arbitrary row update.\n  IF NEW.owner_id IS DISTINCT FROM OLD.owner_id THEN\n    RAISE EXCEPTION 'Permission denied: trip ownership cannot be changed.'\n      USING ERRCODE = '42501';\n  END IF;\n\n  -- Only the current owner may change the membership index used by RLS and\n  -- trip discovery. This prevents a regular member from granting access to\n  -- another account or removing an existing member.\n  IF NEW.member_user_ids IS DISTINCT FROM OLD.member_user_ids\n     AND (auth.uid() IS NULL OR auth.uid()::text <> OLD.owner_id) THEN\n    RAISE EXCEPTION 'Permission denied: only the trip owner can change trip membership.'\n      USING ERRCODE = '42501';\n  END IF;\n\n  RETURN NEW;\nEND;\n$$;\n\nDROP TRIGGER IF EXISTS trg_protect_trip_membership_metadata ON public.trips;\n\nCREATE TRIGGER trg_protect_trip_membership_metadata\n  BEFORE UPDATE ON public.trips\n  FOR EACH ROW\n  EXECUTE FUNCTION public.protect_trip_membership_metadata();\n